def get_wcag_accessibility_audit_catalog() -> List[WcagAccessibilityAuditRecord]:
    """Return complete wcag_accessibility_audit registry."""
    return REGISTRY_WCAG_ACCESSIBILITY_AUDIT


def query_wcag_accessibility_audit_by_difficulty(difficulty_level: str) -> List[WcagAccessibilityAuditRecord]:
    """Filter wcag_accessibility_audit elements matching difficulty."""
    return [item for item in REGISTRY_WCAG_ACCESSIBILITY_AUDIT if item.difficulty == difficulty_level]


def calculate_wcag_accessibility_audit_total_weight() -> float:
    """Compute cumulative weighting of curriculum units."""
    return sum(item.weight for item in REGISTRY_WCAG_ACCESSIBILITY_AUDIT)

